<?php
require_once __DIR__ . '/config/conexion.php';
require_login();
$rows=$pdo->query("SELECT p.*,u.nombre usuario,l.titulo libro,DATEDIFF(CURDATE(),p.fecha_devolucion) dias FROM prestamos p JOIN usuarios u ON u.id_usuario=p.id_usuario JOIN libros l ON l.id_libro=p.id_libro WHERE p.estado_prestamo='Activo' AND p.fecha_devolucion<CURDATE() ORDER BY p.fecha_devolucion ASC")->fetchAll();page_start('Atrasos','atrasos.php');
?>
<div class="page-heading"><div><span class="eyebrow">SEGUIMIENTO</span><h1>Préstamos atrasados</h1><p>Préstamos activos que superaron su fecha límite.</p></div><span class="badge text-bg-danger fs-6"><?= count($rows); ?> atrasados</span></div><section class="panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Usuario</th><th>Libro</th><th>Fecha préstamo</th><th>Fecha límite</th><th>Días de atraso</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $p): ?><tr class="table-danger"><td><?= e($p['usuario']); ?></td><td><?= e($p['libro']); ?></td><td><?= e($p['fecha_prestamo']); ?></td><td><?= e($p['fecha_devolucion']); ?></td><td><strong><?= (int)$p['dias']; ?></strong></td><td><span class="badge rounded-pill text-bg-danger">Atrasado</span></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="text-center text-secondary py-4">No hay préstamos atrasados.</td></tr><?php endif; ?></tbody></table></div></section><?php page_end(); ?>
